"""Evidence evaluation API for the calibration-limits study."""

import json


def _canonical_json(value):
    """Return a stable representation without Python's coercive equality."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )


def evaluate(request, evidence, policy):
    """Evaluate one request against the supplied evidence and policy."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue

        conditions = record.get("conditions", {})
        if any(
            name not in conditions
            or _canonical_json(conditions[name])
            != _canonical_json(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    # Supersedence only has force when the superseding record is itself eligible.
    remaining = []
    for index, record in enumerate(eligible):
        source = record.get("source")
        superseded = False
        for other_index, other in enumerate(eligible):
            if index == other_index:
                continue
            targets = other.get("supersedes", [])
            if isinstance(targets, str):
                targets = [targets]
            if source in targets:
                superseded = True
                break
        if not superseded:
            remaining.append(record)

    if not remaining:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted({record["source"] for record in remaining})
    canonical_values = {_canonical_json(record.get("value")) for record in remaining}
    if len(canonical_values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = remaining[0].get("value")
    return {
        "status": "unsupported" if value is False else "supported",
        "value": value,
        "sources": sources,
        "unknowns": [],
    }

